import * as React from 'react';
import * as InteractiveGridPatternPrimitive from '@exhuma/core';
import { clsx } from 'clsx';

export interface InteractiveGridPatternProps extends React.ComponentPropsWithoutRef<typeof InteractiveGridPatternPrimitive.InteractiveGridPattern> {
  className?: string;
}

export const InteractiveGridPattern = React.forwardRef<HTMLDivElement, InteractiveGridPatternProps>(
  ({ className, children, ...props }, ref) => (
    <InteractiveGridPatternPrimitive.InteractiveGridPattern
      ref={ref}
      className={clsx(
        'absolute inset-0 h-full w-full stroke-gray-400/30 [mask-image:radial-gradient(600px_circle_at_center,white,transparent)]',
        className
      )}
      {...props}
    >
      {children}
    </InteractiveGridPatternPrimitive.InteractiveGridPattern>
  )
);
InteractiveGridPattern.displayName = 'InteractiveGridPattern';

