solid.code:
import { Component, JSX, splitProps } from 'solid-js';

export interface InteractiveGridPatternProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const InteractiveGridPattern: Component<InteractiveGridPatternProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <div
      class={`absolute inset-0 h-full w-full stroke-gray-400/30 [mask-image:radial-gradient(600px_circle_at_center,white,transparent)] ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </div>
  );
};

